{
  "description": "The creature is a large quadrupedal animal shown in profile facing right against a plain light background. Its overall body shape, fur, head and limbs are those of a brown bear, covered in dense shaggy brown fur that is darker on the back and legs and lighter tan on the muzzle and underbelly. Integrated into the furry body are glossy dark brown to black chitinous structures resembling a beetle: a single large curved horn on the forehead and several smooth hard plates around the neck, shoulders, hips and lower forelegs. A row of small oval openings with light rims runs along the side of the torso from behind the shoulder to the hip. The animal stands on four thick legs with clawed paws and has a short stubby tail at the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head with a broad muzzle, lighter tan fur around the nose and mouth, a large black nose at the tip, small dark brown eyes, and a slightly open mouth showing the lower lip",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "a single long glossy dark brown-black horn that rises from the center of the forehead, curves strongly upward and backward then forward to a sharp point, with several small pointed serrations along its inner concave edge and a flared, fused base on the forehead",
      "where": "on top of the head between the ears, extending well above the back"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in thick brown fur, with the right ear more visible than the left",
      "where": "on top of the head behind the base of the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, heavily muscled legs covered in long shaggy dark brown fur, with the forelegs slightly more upright and the hind legs slightly bent",
      "where": "two forelegs under the chest and two hind legs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "large broad paws with dark brown fur on top and five visible light-colored curved claws on each paw, with dark pads underneath",
      "where": "at the bottom of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a very short, stubby tuft of dark brown fur",
      "where": "at the extreme left rear of the body, just above the left hind leg"
    },
    {
      "part": "plates",
      "looks_like": "smooth, shiny, dark reddish-black chitinous plates with light reflections; one large collar-like plate around the back of the neck, a smaller curved plate over each shoulder, a segmented plate over each hip, and narrow band-like plates around the lower forelegs",
      "where": "encircling the neck, covering the top of the shoulders and hips, and wrapping the lower forelegs"
    },
    {
      "part": "markings",
      "looks_like": "a longitudinal row of approximately 18 small vertically oval openings with dark centers and pale cream rims, each surrounded by short bristly hairs, resembling spiracles",
      "where": "along the left side of the torso from the shoulder region to the hip, just above the shoulder plate and continuing backward"
    },
    {
      "part": "fur",
      "looks_like": "dense, long, shaggy fur that is dark chocolate brown on the back, sides and outer legs, lighter golden-brown on the neck, shoulders and flanks, and pale tan on the lower belly and muzzle",
      "where": "covering the entire body except for the nose, claws, horn and chitinous plates"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
